local CommonTopTabNodePath = "Game.UI.Common.CommonTopTabNode"
local CardHeadNodePath = "Game.Behaviours.CardHeadNode"
local PlayerHeadNodePath = "Game.Behaviours.CommonPlayerHeadNode"
------------ define ------------

---@class TrailTeamPreviewDialog
---@field FightText                     	UnityEngine.UI.Text
---@field PlayerLevelText               	UnityEngine.UI.Text
---@field NameText                        UnityEngine.UI.Text
---@field HeadIcon                      	UnityEngine.RectTransform
---@field ScoreText                     	UnityEngine.UI.Extensions.TextPic
---@field CommonHeadItemNode            	UnityEngine.RectTransform
---@field TeamNode                      	UnityEngine.RectTransform
---@field CloseButton                   	UnityEngine.RectTransform
---@field CommonTopNode                   	UnityEngine.RectTransform
local TrailTeamPreviewDialog = Class("TrailTeamPreviewDialog")

function TrailTeamPreviewDialog:__init()
    self.curTab = 1
end

function TrailTeamPreviewDialog:__delete()
    self.controller = nil
end

function TrailTeamPreviewDialog:Awake()

    UIEventProxy.Create(self.CloseButton.gameObject).onPointerClick = function(event)
        UIModule.BackDialog()
    end
    local topMB = GetLuaBehaviour(self.CommonTopNode.gameObject, CommonTopTabNodePath)
    if not isNull(topMB) then
        ---@type SettingMgr
        local setting = SettingMgr:GetInstance():GetSetting(AutoIds.IdSetting740, 'TrailQuestVo')
        if topMB.Env then
            ---@type CommonTopTabNode
            local env = topMB.Env
            env:SetCallbackAction(function(id)
                ---选中不需的标签页时
                self.curTab = id
                self:FreshMainUI()
            end)
            local argument = self.controller.Argument.parameters
            if argument and argument.dojo then
                local dojo = argument.dojo
                local keys = sortByKey(dojo.team)
                local t = {}
                for i, questId in pairs(keys) do
                    ---@type TrailQuestVo
                    local questVo = setting:Get(questId)
                    table.insert(t, questVo.name)
                end
                env:SetTabTexts(t)
            end
        end
    end
end

---FreshMainUI
---刷新页面
function TrailTeamPreviewDialog:FreshMainUI()
    ---传过来的参数
    local argument = self.controller.Argument.parameters
    if argument and argument.dojo then
        local dojo = argument.dojo
        local playerHeadNode = GetLuaBehaviour(self.HeadIcon.gameObject, PlayerHeadNodePath)
        if not KTool.IsNull(playerHeadNode) and not isNull(playerHeadNode.Env) then
            ---@type CommonPlayerHeadNode
            local env = playerHeadNode.Env
            env:FreshAvatarFrame(dojo.avatar, dojo.avatarFrame)
        end
        KTool.DestroyGameObjectChildren(self.TeamNode.gameObject, true)
        local keys = sortByKey(dojo.team)
        local questDojo = dojo.team[tostring(keys[self.curTab])]
        self.ScoreText.text = string.format('%s _fish_', tostring(math.floor(checkNumber(questDojo.score))))
        if table.count(questDojo.cards) > 0 then
            for i, v in pairs(questDojo.cards) do
                local go = KTool.Instantiate(self.TeamNode.gameObject, self.CommonHeadItemNode.gameObject)
                KTool.SetActive(go, true)
                local headNode = GetLuaBehaviour(go, CardHeadNodePath)
                if not KTool.IsNull(headNode) then
                    if isNull(headNode.Env) then
                        headNode:Init()
                    end
                    ---@type CardHeadNode
                    local env = headNode.Env
                    env:SetCallBack(function (id, index)
                        CardUtils.ShowCardPreview({previewType = Constants.UICultivateCardPreviewType.Virtual, cards = { v }}, {
                            { id = Constants.UITypeIds.UITrailStageHome},
                            { id = Constants.UITypeIds.UITrailStageRankDialog},
                            { id = Constants.UITypeIds.UITrailStageTeamPreviewDialog},
                        })
                    end)
                    env:FreshNode(v, true, i)
                    CfUtils.SetScale(env.HeadImage.gameObject, Vector3.New(0.86,0.86,1))
                end
            end
        end
    end
end

function TrailTeamPreviewDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local argument = self.controller.Argument.parameters
        if argument and argument.dojo then
            local dojo = argument.dojo
            self.NameText.text = dojo.name
            self.PlayerLevelText.text = tostring(dojo.level)
            self.FightText.text = tostring(dojo.score)
        end
        self:FreshMainUI()
    end))
    return coWait
end

function TrailTeamPreviewDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return TrailTeamPreviewDialog